def send_weights(tensors, cap):
    offset, bucket = 0, []
    for name, size in tensors:
        if offset + size > cap and bucket:
            flush(bucket)        # metadata, wait for ack
            offset, bucket = 0, []
        if size > cap:
            send_direct(name)    # bigger than any bucket
            continue
        bucket.append(name)      # copy into shared buffer
        offset += size
    flush(bucket)                # the last bucket
